package ma.projet.service; import ma.projet.beans.*; import ma.projet.util.HibernateUtil; import org.hibernate.Session; import java.time.LocalDate; import java.util.*; public class FemmeService extends GenericService<Femme>{public FemmeService(){super(Femme.class);} public long enfantsEntre(Long id,LocalDate a,LocalDate b){try(Session s=HibernateUtil.getSessionFactory().openSession()){return ((Number)s.createNativeQuery("select coalesce(sum(nbrEnfant),0) from mariage where femme_id=:id and date_debut between :a and :b").setParameter("id",id).setParameter("a",a).setParameter("b",b).getSingleResult()).longValue();}} public List<Femme> marieesDeuxFois(){try(Session s=HibernateUtil.getSessionFactory().openSession()){return s.createQuery("select f from Femme f join f.mariages m group by f having count(m)>=2",Femme.class).list();}} public Optional<Femme> plusAgee(){return findAll().stream().min(Comparator.comparing(Femme::getDateNaissance));}}
